import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<Integer, Long> tab1 = new HashMap<>();
    static Map<String, Long> tab2 = new HashMap<>();

    public static long computeNum1(int n) {
        if (n < 0) {
            return 0;
        } else if (n < 2) {
            return 1;
        } else if (!tab1.containsKey(n)) {
            long total = 0;
            for (int i = 0; i < n; i++) {
                total += computeNum1(i) * computeNum1(n - 1 - i);
            }
            tab1.put(n, total);
        }
        return tab1.get(n);
    }

    public static long computeNum2(int n, int h) {
        if (n < 0 || h <= 0 || n >= Math.pow(2, h - 1)) {
            return 0;
        } else if (n < 2) {
            return 1;
        } else if (n < h) {
            return computeNum1(n);
        } else {
            String key = n + "," + h;
            if (!tab2.containsKey(key)) {
                long total = 0;
                for (int i = 0; i < n; i++) {
                    total += computeNum2(i, h - 1) * computeNum2(n - 1 - i, h - 1);
                }
                tab2.put(key, total);
            }
            return tab2.get(key);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();
        System.out.println(computeNum1(n) - computeNum2(n, h));
        scanner.close();
    }
}
